        [25, 'Agree with thine adversary quickly, whiles thou art in the way with him; lest at any time the adversary deliver thee to the judge, and the judge deliver thee to the officer, and thou be cast into prison.', ['w' => [0, 203]]],
        [26, 'Verily I say unto thee, Thou shalt by no means come out thence, till thou hast paid the uttermost farthing.', ['w' => [0, 107]]],
