        [17, 'But thou, when thou fastest, anoint thine head, and wash thy face;', ['w' => [0, 66]]],
        [18, 'That thou appear not unto men to fast, but unto thy Father which is in secret: and thy Father, which seeth in secret, shall reward thee openly.', ['w' => [0, 143]]],
        [19, 'Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal:', ['p' => 1, 'w' => [0, 124]]],
