        [23, 'But if thine eye be evil, thy whole body shall be full of darkness. If therefore the light that is in thee be darkness, how great is that darkness!', ['w' => [0, 147], 'i' => [130, 132]]],
        [24, 'No man can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.', ['p' => 1, 'w' => [0, 170]]],
