        [33, 'But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.', ['w' => [0, 106]]],
        [34, 'Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.', ['w' => [0, 146], 'i' => [126, 128]]],
